  4905  static int
  4906  md_process_code_block_contents(MD_CTX* ctx, int is_fenced, const MD_VERBATIMLINE* lines, MD_SIZE n_lines)
  4907  {
  4908      if(is_fenced) {
  4909          /* Skip the first line in case of fenced code: It is the fence.
  4910           * (Only the starting fence is present due to logic in md_analyze_line().) */
  4911          lines++;
  4912          n_lines--;
  4913      } else {
  4914          /* Ignore blank lines at start/end of indented code block. */
  4915          while(n_lines > 0  &&  lines[0].beg == lines[0].end) {
  4916              lines++;
  4917              n_lines--;
  4918          }
  4919          while(n_lines > 0  &&  lines[n_lines-1].beg == lines[n_lines-1].end) {
  4920              n_lines--;
  4921          }
  4922      }
  4923
  4924      if(n_lines == 0)
  4925          return 0;
  4926
  4927      return md_process_verbatim_block_contents(ctx, MD_TEXT_CODE, lines, n_lines);
  4928  }
