  4930  static int
  4931  md_setup_fenced_code_detail(MD_CTX* ctx, const MD_BLOCK* block, MD_BLOCK_CODE_DETAIL* det,
  4932                              MD_ATTRIBUTE_BUILD* info_build, MD_ATTRIBUTE_BUILD* lang_build)
  4933  {
  4934      const MD_VERBATIMLINE* fence_line = (const MD_VERBATIMLINE*)(block + 1);
  4935      OFF beg = fence_line->beg;
  4936      OFF end = fence_line->end;
  4937      OFF lang_end;
  4938      CHAR fence_ch = CH(fence_line->beg);
  4939      int ret = 0;
  4940
  4941      /* Skip the fence itself. */
  4942      while(beg < ctx->size  &&  CH(beg) == fence_ch)
  4943          beg++;
  4944      /* Trim initial spaces. */
  4945      while(beg < ctx->size  &&  CH(beg) == _T(' '))
  4946          beg++;
  4947
  4948      /* Trim trailing spaces. */
  4949      while(end > beg  &&  CH(end-1) == _T(' '))
  4950          end--;
  4951
  4952      /* Build info string attribute. */
  4953      MD_CHECK(md_build_attribute(ctx, STR(beg), end - beg, 0, &det->info, info_build));
  4954
  4955      /* Build info string attribute. */
  4956      lang_end = beg;
  4957      while(lang_end < end  &&  !ISWHITESPACE(lang_end))
  4958          lang_end++;
  4959      MD_CHECK(md_build_attribute(ctx, STR(beg), lang_end - beg, 0, &det->lang, lang_build));
  4960
  4961      det->fence_char = fence_ch;
  4962
  4963  abort:
  4964      return ret;
  4965  }
