  4967  static int
  4968  md_process_leaf_block(MD_CTX* ctx, const MD_BLOCK* block)
  4969  {
  4970      union {
  4971          MD_BLOCK_H_DETAIL header;
  4972          MD_BLOCK_CODE_DETAIL code;
  4973          MD_BLOCK_TABLE_DETAIL table;
  4974      } det;
  4975      MD_ATTRIBUTE_BUILD info_build = { 0 };
  4976      MD_ATTRIBUTE_BUILD lang_build = { 0 };
  4977      int is_in_tight_list;
  4978      int clean_fence_code_detail = FALSE;
  4979      int ret = 0;
  4980
  4981      memset(&det, 0, sizeof(det));
  4982
  4983      if(ctx->n_containers == 0)
  4984          is_in_tight_list = FALSE;
  4985      else
  4986          is_in_tight_list = !ctx->containers[ctx->n_containers-1].is_loose;
  4987
  4988      switch(block->type) {
  4989          case MD_BLOCK_H:
  4990              det.header.level = block->data;
  4991              break;
  4992
  4993          case MD_BLOCK_CODE:
  4994              /* For fenced code block, we may need to set the info string. */
  4995              if(block->data != 0) {
  4996                  memset(&det.code, 0, sizeof(MD_BLOCK_CODE_DETAIL));
  4997                  clean_fence_code_detail = TRUE;
  4998                  MD_CHECK(md_setup_fenced_code_detail(ctx, block, &det.code, &info_build, &lang_build));
  4999              }
  5000              break;
  5001
  5002          case MD_BLOCK_TABLE:
  5003              det.table.col_count = block->data;
  5004              det.table.head_row_count = 1;
  5005              det.table.body_row_count = block->n_lines - 2;
  5006              break;
  5007
  5008          default:
  5009              /* Noop. */
  5010              break;
  5011      }
  5012
  5013      if(!is_in_tight_list  ||  block->type != MD_BLOCK_P)
  5014          MD_ENTER_BLOCK(block->type, (void*) &det);
  5015
  5016      /* Process the block contents accordingly to is type. */
  5017      switch(block->type) {
  5018          case MD_BLOCK_HR:
  5019              /* noop */
  5020              break;
  5021
  5022          case MD_BLOCK_CODE:
  5023              MD_CHECK(md_process_code_block_contents(ctx, (block->data != 0),
  5024                              (const MD_VERBATIMLINE*)(block + 1), block->n_lines));
  5025              break;
  5050      }
  5051      return ret;
  5052  }
