  5056  static int
  5057  md_process_all_blocks(MD_CTX* ctx)
  5058  {
  5059      MD_TEXTTYPE adm_substr_types[1] = { MD_TEXT_NORMAL };
  5060      MD_OFFSET adm_substr_offsets[2];
  5061      int byte_off = 0;
  5062      int ret = 0;
  5063
  5064      /* ctx->containers now is not needed for detection of lists and list items
  5065       * so we reuse it for tracking what lists are loose or tight. We rely
  5066       * on the fact the vector is large enough to hold the deepest nesting
  5067       * level of lists. */
  5068      ctx->n_containers = 0;
  5069
  5070      while(byte_off < ctx->n_block_bytes) {
  5071          MD_BLOCK* block = (MD_BLOCK*)((char*)ctx->block_bytes + byte_off);
  5072          union {
  5073              MD_BLOCK_UL_DETAIL ul;
  5074              MD_BLOCK_OL_DETAIL ol;
  5075              MD_BLOCK_LI_DETAIL li;
  5076              MD_BLOCK_ADMONITION_DETAIL adm;
  5077          } det;
  5078
  5079          switch(block->type) {
  5080              case MD_BLOCK_UL:
  5081                  det.ul.is_tight = (block->flags & MD_BLOCK_LOOSE_LIST) ? FALSE : TRUE;
  5082                  det.ul.mark = (CHAR) block->data;
  5083                  break;
  5084
  5085              case MD_BLOCK_OL:
  5086                  det.ol.start = block->n_lines;
  5087                  det.ol.is_tight = (block->flags & MD_BLOCK_LOOSE_LIST) ? FALSE : TRUE;
  5088                  det.ol.mark_delimiter = (CHAR) block->data;
  5089                  break;
  5090
  5091              case MD_BLOCK_LI:
  5092                  det.li.is_task = (block->data != 0);
  5093                  det.li.task_mark = (CHAR) block->data;
  5094                  det.li.task_mark_offset = (OFF) block->n_lines;
  5095                  break;
  5096
  5097              case MD_BLOCK_ADMONITION:
  5098                  adm_substr_offsets[0] = 0;
  5099                  adm_substr_offsets[1] = md_strlen(MD_ADMONITION_TAGS[block->data]);
  5100
  5101                  det.adm.type.text = MD_ADMONITION_TAGS[block->data];
  5102                  det.adm.type.size = adm_substr_offsets[1];
  5103                  det.adm.type.substr_types = adm_substr_types;
  5104                  det.adm.type.substr_offsets = adm_substr_offsets;
  5105                  break;
  5106
  5107              default:
  5108                  /* noop */
  5109                  break;
  5110          }
  5111
  5112          if(block->flags & MD_BLOCK_CONTAINER) {
  5113              if(block->flags & MD_BLOCK_CONTAINER_CLOSER) {
  5114                  MD_LEAVE_BLOCK(block->type, &det);
  5115
  5116                  if(block->type == MD_BLOCK_UL || block->type == MD_BLOCK_OL ||
  5117                     block->type == MD_BLOCK_QUOTE || block->type == MD_BLOCK_ADMONITION)
  5118                      ctx->n_containers--;
  5119              }
  5120
  5121              if(block->flags & MD_BLOCK_CONTAINER_OPENER) {
  5122                  MD_ENTER_BLOCK(block->type, &det);
  5123
  5124                  if(block->type == MD_BLOCK_UL || block->type == MD_BLOCK_OL) {
  5125                      ctx->containers[ctx->n_containers].is_loose = (block->flags & MD_BLOCK_LOOSE_LIST) ? TRUE : FALSE;
  5126                      ctx->n_containers++;
  5127                  } else if(block->type == MD_BLOCK_QUOTE  ||  block->type == MD_BLOCK_ADMONITION) {
  5128                      /* This causes that any text in a block quote, even if
  5129                       * nested inside a tight list item, is wrapped with
  5130                       * <p>...</p>. */
  5450          off++;
  5451
  5452      /* Optionally, space(s) or tabs can follow. */
  5453      while(off < ctx->size  &&  ISBLANK(off))
  5454          off++;
  5455
  5456      /* But nothing more is allowed on the line. */
  5457      if(off < ctx->size  &&  !ISNEWLINE(off))
  5458          return FALSE;
  5459
  5460      *p_level = (CH(beg) == _T('=') ? 1 : 2);
  5461      *p_end = off;
  5462      return TRUE;
  5463  }
