  5525  static int
  5526  md_is_opening_code_fence(MD_CTX* ctx, OFF beg, OFF* p_end)
  5527  {
  5528      OFF off = beg;
  5529
  5530      while(off < ctx->size && CH(off) == CH(beg))
  5531          off++;
  5532
  5533      /* Fence must have at least three characters. */
  5534      if(off - beg < 3)
  5535          return FALSE;
  6220                  line->indent = md_line_indentation(ctx, total_indent, off, &off);
  6221                  total_indent += line->indent;
  6222                  line->beg = off;
  6223
  6224                  /* Some of the following whitespace actually still belongs to the mark. */
  6225                  if(off >= ctx->size || ISNEWLINE(off)) {
  6226                      container.contents_indent++;
  6227                  } else if(line->indent <= ctx->code_indent_offset) {
  6228                      container.contents_indent += line->indent;
  6229                      line->indent = 0;
  6230                  } else {
  6231                      container.contents_indent += 1;
  6232                      line->indent--;
  6233                  }
  6234
  6235                  ctx->containers[n_parents].mark_indent = container.mark_indent;
  6236                  ctx->containers[n_parents].contents_indent = container.contents_indent;
  6237
  6238                  n_brothers++;
  6239                  continue;
  6240              }
  6241          }
  6242
  6243          /* Check for indented code.
  6244           * Note indented code block cannot interrupt a paragraph. */
  6245          if(line->indent >= ctx->code_indent_offset  &&  (pivot_line->type != MD_LINE_TEXT)) {
  6246              line->type = MD_LINE_INDENTEDCODE;
  6247              line->indent -= ctx->code_indent_offset;
  6248              line->data = 0;
  6249              break;
  6250          }
  6251
  6252          /* Check for start of a new container block. */
  6253          if(line->indent < ctx->code_indent_offset  &&
  6254             md_is_container_mark(ctx, line->indent, off, &off, &container))
  6255          {
  6256              if(pivot_line->type == MD_LINE_TEXT  &&  n_parents == ctx->n_containers  &&
  6257                          (off >= ctx->size || ISNEWLINE(off))  &&  container.ch != _T('>'))
  6258              {
  6259                  /* Noop. List mark followed by a blank line cannot interrupt a paragraph. */
  6260              } else if(pivot_line->type == MD_LINE_TEXT  &&  n_parents == ctx->n_containers  &&
  6261                          ISANYOF2_(container.ch, _T('.'), _T(')'))  &&  container.start != 1)
  6262              {
  6263                  /* Noop. Ordered list cannot interrupt a paragraph unless the start index is 1. */
  6264              } else {
  6265                  total_indent += container.contents_indent - container.mark_indent;
  6266                  line->indent = md_line_indentation(ctx, total_indent, off, &off);
  6267                  total_indent += line->indent;
  6268
  6269                  line->beg = off;
  6270                  line->data = container.ch;
  6271
  6272                  /* Some of the following whitespace actually still belongs to the mark. */
  6273                  if(off >= ctx->size || ISNEWLINE(off)) {
  6274                      container.contents_indent++;
  6275                  } else if(line->indent <= ctx->code_indent_offset) {
  6276                      container.contents_indent += line->indent;
  6277                      line->indent = 0;
  6278                  } else {
  6279                      container.contents_indent += 1;
  6280                      line->indent--;
  6281                  }
  6282
  6283                  if(n_brothers + n_children == 0)
  6284                      pivot_line = &md_dummy_blank_line;
  6285
  6286                  if(n_children == 0)
  6287                      MD_CHECK(md_leave_child_containers(ctx, n_parents + n_brothers));
  6288
  6289                  n_children++;
  6290                  MD_CHECK(md_push_container(ctx, &container));
  6291                  continue;
  6292              }
  6293          }
  6294
  6295          /* Check whether we are table continuation. */
  6296          if(pivot_line->type == MD_LINE_TABLE  &&  n_parents == ctx->n_containers) {
  6297              line->type = MD_LINE_TABLE;
  6298              break;
  6299          }
  6300
  6301          /* Check for ATX header. */
  6302          if(line->indent < ctx->code_indent_offset  &&
  6303                  off < ctx->size  &&  CH(off) == _T('#'))
  6304          {
  6305              unsigned level;
  6306
  6307              if(md_is_atxheader_line(ctx, off, &line->beg, &off, &level)) {
  6308                  line->type = MD_LINE_ATXHEADER;
  6309                  line->data = level;
  6310                  break;
  6311              }
  6312          }
  6313
  6314          /* Check whether we are starting code fence. */
  6315          if(line->indent < ctx->code_indent_offset  &&
  6316                  off < ctx->size  &&  ISANYOF2(off, _T('`'), _T('~')))
  6317          {
  6318              if(md_is_opening_code_fence(ctx, off, &off)) {
  6319                  line->type = MD_LINE_FENCEDCODE;
  6320                  line->data = 1;
  6321                  line->enforce_new_block = TRUE;
  6322                  break;
  6323              }
  6324          }
  6325
  6326          /* Check for start of raw HTML block. */
  6327          if(off < ctx->size  &&  CH(off) == _T('<')
  6328              &&  !(ctx->parser.flags & MD_FLAG_NOHTMLBLOCKS))
  6329          {
  6330              ctx->html_block_type = md_is_html_block_start_condition(ctx, off);
  6331
  6332              /* HTML block type 7 cannot interrupt paragraph. */
  6333              if(ctx->html_block_type == 7  &&  pivot_line->type == MD_LINE_TEXT)
  6334                  ctx->html_block_type = 0;
  6335
  6336              if(ctx->html_block_type > 0) {
  6337                  /* The line itself also may immediately close the block. */
  6338                  if(md_is_html_block_end_condition(ctx, off, &off) == ctx->html_block_type) {
  6339                      /* Make sure this is the last line of the block. */
  6340                      ctx->html_block_type = 0;
  6341                  }
  6342
  6343                  line->enforce_new_block = TRUE;
  6344                  line->type = MD_LINE_HTML;
  6345                  break;
  6346              }
  6347          }
  6348
  6349          /* Check for table underline. */
  6350          if((ctx->parser.flags & MD_FLAG_TABLES)  &&  pivot_line->type == MD_LINE_TEXT
  6351              &&  off < ctx->size  &&  ISANYOF3(off, _T('|'), _T('-'), _T(':'))
  6352              &&  n_parents == ctx->n_containers)
  6353          {
  6354              unsigned col_count;
  6355
  6356              if(ctx->current_block != NULL  &&  ctx->current_block->n_lines == 1  &&
  6357                  md_is_table_underline(ctx, off, &off, &col_count))
  6358              {
  6359                  line->data = col_count;
  6360                  line->type = MD_LINE_TABLEUNDERLINE;
  6361                  break;
  6362              }
  6363          }
  6364
  6365          /* By default, we are normal text line. */
  6366          line->type = MD_LINE_TEXT;
  6367          if(pivot_line->type == MD_LINE_TEXT  &&  n_brothers + n_children == 0) {
  6368              /* Lazy continuation. */
  6369              n_parents = ctx->n_containers;
  6370          }
